# Generated by manage.py generate_test_cases.
from django.contrib.auth import authenticate, get_user_model
from django.contrib.auth.models import Permission
from django.contrib.contenttypes.models import ContentType
from django.urls import resolve, reverse

from bloomerp.models import FieldPolicy, Policy, RowPolicy
from bloomerp.models.access_control.row_policy_rule import RowPolicyRule
from bloomerp.models.users.user import User
from bloomerp.tests.base import (
    BloomerpModelViewTestCase,
    ExpectedResult,
    RequestScenario,
    ModelRequestScenario,
)
from bloomerp.utils.models import get_detail_view_url


class TestUserCreateView(BloomerpModelViewTestCase):
    """Tests class `UserCreateView` from `bloomerp/views/users/create.py`."""

    view_name = 'add'
    model = User

    def get_test_scenarios(self) -> list[RequestScenario]:
        return [
            RequestScenario(
                name="Administrator sees password-aware user creation form",
                description=(
                    "UC: An administrator opens the create-user view.\n"
                    "Expected Result: Username, password confirmation, multipart, and HTMX controls render."
                ),
                user=self.admin_user,
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text('name="username"'),
                        self.contains_text('name="password1"'),
                        self.contains_text('name="password2"'),
                        self.contains_text('enctype="multipart/form-data"'),
                        self.contains_text('hx-encoding="multipart/form-data"'),
                        self.contains_text('hx-push-url="true"'),
                    ]
                ),
            ),
            RequestScenario(
                name="Administrator creates a user with exact submitted password",
                description=(
                    "UC: An administrator submits a valid new-user form.\n"
                    "Expected Result: The user is created, can authenticate, and the response redirects to its detail view."
                ),
                method="POST",
                user=self.admin_user,
                data=self.user_payload("created-user"),
                expected=ExpectedResult(
                    status_code=302,
                    response_validators=self.created_user_is_valid_and_redirected,
                ),
            ),
            RequestScenario(
                name="Policy-backed staff user can create users",
                description=(
                    "UC: A non-superuser receives create access to the User model.\n"
                    "Expected Result: They can create a user whose submitted password authenticates."
                ),
                method="POST",
                user=self.normal_user,
                data=self.user_payload("policy-created-user"),
                prepare=self.grant_user_create_policy,
                expected=ExpectedResult(
                    status_code=302,
                    response_validators=self.policy_created_user_authenticates,
                ),
            ),
            RequestScenario(
                name="User create route and default layout target active User model",
                description=(
                    "UC: A project uses the active User model.\n"
                    "Expected Result: The route is bound to it and its layout exposes identity and access fields."
                ),
                user=self.admin_user,
                expected=ExpectedResult(response_validators=self.route_and_layout_target_user),
            ),
        ]

    @staticmethod
    def user_payload(username):
        return {
            "username": username,
            "email": f"{username}@example.com",
            "password1": "exact-test-password-123",
            "password2": "exact-test-password-123",
        }

    def grant_user_create_policy(self, _scenario):
        content_type = ContentType.objects.get_for_model(User)
        permission = Permission.objects.get(content_type=content_type, codename="add_user")
        row_policy = RowPolicy.objects.create(
            content_type=content_type,
            name="Create users row policy",
        )
        row_rule = RowPolicyRule.objects.create(
            row_policy=row_policy,
            rule={
                "connector": "OR",
                "conditions": [
                    {
                        "application_field_id": "__all__",
                        "operator": "equals",
                        "value": "",
                    }
                ],
            },
        )
        row_rule.add_permission("add_user")
        field_policy = FieldPolicy.objects.create(
            content_type=content_type,
            name="Create users field policy",
            rule={"__all__": ["add_user"]},
        )
        policy = Policy.objects.create(
            name="Create users policy",
            row_policy=row_policy,
            field_policy=field_policy,
        )
        policy.assign_user(self.normal_user)
        policy.global_permissions.add(permission)

    def created_user_is_valid_and_redirected(self, response):
        payload = self.user_payload("created-user")
        user = User.objects.get(username=payload["username"])
        return (
            user.email == payload["email"]
            and authenticate(username=user.username, password=payload["password1"]) == user
            and response.headers["Location"]
            == reverse(get_detail_view_url(User), kwargs={"pk": user.pk})
        )

    def policy_created_user_authenticates(self, _response):
        payload = self.user_payload("policy-created-user")
        user = User.objects.get(username=payload["username"])
        return authenticate(username=user.username, password=payload["password1"]) == user

    def route_and_layout_target_user(self, response):
        route_matches = resolve(response.wsgi_request.path).func.view_initkwargs["model"] is get_user_model()
        layout = User.bloomerp_config.detail_view_settings.get_default_layout()
        field_ids = [item.id for row in layout.rows for item in row.items]
        return route_matches and {"username", "email", "is_active", "groups"}.issubset(field_ids)
